  -- ks4-16-consent-images-law
  perform pg_temp.gc_set('ks4-16-consent-images-law', 'slides', '{5,"question"}', 'b16808bce5a818ff49171d6cd8588d84', null, $gc394$"Retrieval from the manipulation lesson. A message says you must decide right now, this second, or you will lose your chance. Which persuasion technique is that?"$gc394$::jsonb);
  perform pg_temp.gc_set('ks4-16-consent-images-law', 'slides', '{5,"script"}', '4cffc91abea9961be72ddf2ac7206492', null, $gc394$"Thirty seconds of silent thinking, then take answers. In the manipulation lesson you learned to name the technique: urgency, outrage, flattery, FOMO. Land the bridge clearly: today those same techniques show up in a much more personal place, in messages asking for images. Naming the technique works exactly the same way there."$gc394$::jsonb);
  perform pg_temp.gc_set('ks4-16-consent-images-law', 'slides', '{13,"script"}', '39b3025b5a60def4e52b39e60e6d1d70', null, $gc394$"Give the room a silent read, then work through it line by line, naming techniques like the manipulation lesson. You would if you cared is guilt used as a lever. Everyone sends them is false social proof, and it is factually wrong, most people do not. I would never show anyone is a promise nobody can enforce once an image exists. Why are you making this a big deal reverses the blame onto the person saying no. Four sentences, four techniques. Then say clearly: a yes produced by this message would not be consent, because it was not freely given. If this scenario prompts any pupil to disclose something similar, follow your safeguarding policy, speak to them privately and involve your DSL the same day."$gc394$::jsonb);
  perform pg_temp.gc_set('ks4-16-consent-images-law', 'assessment', '{"teacher_judgement"}', null, $gc394${"scale":["working_towards","met","exceeded"],"default":"met","one_tap":true}$gc394$::jsonb, $gc394${"scale":["secure","developing","revisit"],"descriptors":{"secure":"Names the four properties of real consent, states the law has no both agreed exception, and gives a friend Report Remove.","developing":"Reaches Report Remove for a friend but skips the two reassurances: it is not your fault, you are not in trouble.","revisit":"Says it is legal if both are under 18 and agree, or that nothing can be done once an image is out."}}$gc394$::jsonb);

  -- ks4-17-sextortion
  perform pg_temp.gc_set('ks4-17-sextortion', 'slides', '{23,"script"}', '5a35ac24251371375dee4723c689a5bc', null, $gc394$"First of two exit questions, and together they are the printed exit quiz, so run it in quiet, individual conditions: thirty seconds of silence, then everyone answers on their own device or sheet, nobody calls out. This one tests the full pathway. A pupil who picks delete and block has heard block and move on advice from other contexts, so the feedback matters: blocking is fine, but only after telling and saving evidence. Note anyone who misses this for a quiet revisit, this is the module where a wrong answer is not one you leave until next term."$gc394$::jsonb);
  perform pg_temp.gc_set('ks4-17-sextortion', 'slides', '{24,"script"}', 'd5a702384458c266efc1ed08131c4d4a', null, $gc394$"The most important ninety seconds of the hour. This question is the outcome of the lesson in exam form: it is not my fault and I know who to tell. If even one pupil answers true, address it to the whole room without looking at anyone: the belief that it is your fault is the blackmailer's best weapon, and it is false in the eyes of the law and everyone who will help you. Collect the exit quizzes in yourself, they show you who to revisit and are your radar for follow up."$gc394$::jsonb);
  perform pg_temp.gc_set('ks4-17-sextortion', 'assessment', '{"teacher_judgement"}', null, $gc394${"scale":["working_towards","met","exceeded"],"default":"met","one_tap":true}$gc394$::jsonb, $gc394${"scale":["secure","developing","revisit"],"descriptors":{"secure":"Gives the three lifelines unprompted, do not pay, do not keep it secret, report it, and says the blackmailer committed the crime.","developing":"Knows the three lifelines but still picks delete, block and say nothing, or cannot name Report Remove, CEOP or Childline.","revisit":"Says sending the image makes it the victim's fault, that paying once makes it stop, or names nobody they would tell."}}$gc394$::jsonb);

