  perform pg_temp.gc_set('ks4-19-readiness-at-16', 'slides', '{5,"options",1,"feedback"}', '990f5eafc8f6a291c34ea2cdb874303a', null, $gc394$"Exactly. Content that hands you an enemy is recruiting you, not informing you. That is the pipeline's signature, and it matters today more than ever."$gc394$::jsonb);
  perform pg_temp.gc_set('ks4-19-readiness-at-16', 'slides', '{5,"options",2,"text"}', '8eb69828e190eb6216f55ac07d763d88', null, $gc394$"Does the person posting have a big following?"$gc394$::jsonb);
  perform pg_temp.gc_set('ks4-19-readiness-at-16', 'slides', '{5,"options",2,"feedback"}', 'fea69daa5b4673fff070ff98cf8c3d6e', null, $gc394$"Follower count is not one of the three questions. The third asks who you are being turned against, because content that hands you an enemy is recruiting you."$gc394$::jsonb);
  perform pg_temp.gc_set('ks4-19-readiness-at-16', 'slides', '{27,"script"}', '8c28a842fa3e4cd81e8cc1d69594c66c', null, $gc394$"First of two exit checks. Run it in silence, no conferring: everyone answers on their own device, or writes the letter on their question card, and the options shuffle so nobody copies a neighbour. These two checks and the printed exit quiz show you who to revisit. A pupil picking the borrowed account option has not connected the workaround cost to arrival day, note them for a quiet follow up, without any suggestion that the answer was autobiographical."$gc394$::jsonb);
  perform pg_temp.gc_set('ks4-19-readiness-at-16', 'slides', '{28,"script"}', '56cbba2e403e7473abca5f716d66f19d', null, $gc394$"Second exit check, still silent and independent: everyone on their own device or question card, ten seconds of thinking before anyone taps. This is the thesis question: it proves whether pupils leave with the honest position or with one of the two easy ones, the ban fixed everything or the ban is pointless. Anyone choosing either wrong option goes on your list to revisit next lesson, the distinction is the whole module."$gc394$::jsonb);
  perform pg_temp.gc_set('ks4-19-readiness-at-16', 'slides', '{33,"script"}', 'fc445c7f1181d1c5b13c99e4b1b3433c', null, $gc394$"Let DiGi land the ending, the lines appear on their own. Exit quizzes are collected as this plays, they show you who to revisit next lesson. If you collected a brilliant exit rule during practice, read it out now with the writer's permission, it is the perfect final note."$gc394$::jsonb);
  perform pg_temp.gc_set('ks4-19-readiness-at-16', 'assessment', '{"teacher_judgement"}', null, $gc394${"scale":["working_towards","met","exceeded"],"default":"met","one_tap":true}$gc394$::jsonb, $gc394${"scale":["secure","developing","revisit"],"descriptors":{"secure":"Writes an arrival plan with all three parts, defaults, first week audit, exit rule, and explains why habits beat rules.","developing":"Names the three parts of the arrival plan but needs the sentence starters to write their own.","revisit":"Says the ban makes social media safe by 16, or that a workaround is early access to the same experience."}}$gc394$::jsonb);

  -- ks5-20-ai-mastery-data-rights
  perform pg_temp.gc_set('ks5-20-ai-mastery-data-rights', 'slides', '{8,"prompt"}', '203125e8624e88177519880af9793f8a', null, $gc394$"Take the last thing you asked an AI tool. Rewrite it as a brief: context, constraints, a clear job."$gc394$::jsonb);
  perform pg_temp.gc_set('ks5-20-ai-mastery-data-rights', 'slides', '{8,"script"}', 'aaadd8a8ca39031982565d98c33c9c83', null, $gc394$"Sixty seconds in pairs. They rewrite the prompt they named at the start as a brief: context, constraints, a clear job. Hear one rewrite aloud. The next two slides explain why a good brief is only half of it."$gc394$::jsonb);
  perform pg_temp.gc_set('ks5-20-ai-mastery-data-rights', 'slides', '{8,"lookFor"}', '644c47a803fc3769fffbab7fe16b0a67', null, $gc394$"All three parts in the rewrite: context, constraints, a clear job. A vague prompt gets the average of the internet, a precise one something worth editing."$gc394$::jsonb);
  perform pg_temp.gc_set('ks5-20-ai-mastery-data-rights', 'assessment', '{"teacher_judgement"}', null, $gc394${"scale":["working_towards","met","exceeded"],"default":"met","one_tap":true}$gc394$::jsonb, $gc394${"scale":["secure","developing","revisit"],"descriptors":{"secure":"Checks a claim somewhere the AI did not write, defends the verdict aloud, and names the data trade behind a free tool.","developing":"Says use it, check it, own it, but still reads a fluent answer as an accurate one.","revisit":"Says hallucinations will be fixed by the next update, or that companies have their data anyway so it does not matter."}}$gc394$::jsonb);

  -- ks5-21-digital-identity-future-work
  perform pg_temp.gc_set('ks5-21-digital-identity-future-work', 'assessment', '{"teacher_judgement"}', null, $gc394${"scale":["working_towards","met","exceeded"],"default":"met","one_tap":true}$gc394$::jsonb, $gc394${"scale":["secure","developing","revisit"],"descriptors":{"secure":"Splits one career into tasks that compress and tasks that expand, and names a human skill they are choosing to build.","developing":"Runs the endurance test on the worksheet items but gives job level verdicts, such as medicine is safe or coding is doomed.","revisit":"Says AI will take all the jobs so there is no point preparing, or that a blank search result is safest."}}$gc394$::jsonb);

  -- could-you-be-an-entrepreneur
  perform pg_temp.gc_set('could-you-be-an-entrepreneur', 'assessment', '{"teacher_judgement"}', null, null, $gc394${"scale":["secure","developing","revisit"],"descriptors":{"secure":"Uses the real figures to weigh up working for yourself, and plans a small try with an adult who knows.","developing":"Recalls the figures on how long businesses last and what they pay, but plans a try with no adult in it.","revisit":"Says most new businesses fail in their first year, or that working for yourself always pays more than a job."}}$gc394$::jsonb);

