  perform pg_temp.gc_set('should-people-wear-smart-glasses', 'assessment', '{"teacher_judgement"}', null, null, $gc394${"scale":["secure","developing","revisit"],"descriptors":{"secure":"Says ask, say, tell without prompting, gives one good bit and one worry, and names a place to be extra careful.","developing":"Says ask first, but treats the light as the same as asking, or needs the card to say please stop.","revisit":"Says smart glasses are only for spying, or keeps quiet about being filmed because saying no feels rude."}}$gc394$::jsonb);

